.record-notes { white-space: pre-wrap; }
.review-note { border-inline-start: 4px solid var(--secondary); padding-inline-start: var(--space-control); }
#history-error { color: var(--error); background: var(--error-surface); padding: var(--space-control); border-radius: var(--corner); overflow-wrap: anywhere; }
#history-error:empty { display: none; }
select[aria-invalid="true"] { border-color: var(--error); }
dt { font-weight: 600; }
dd { margin: 0 0 var(--space-md); overflow-wrap: anywhere; white-space: pre-wrap; font-variant-numeric: tabular-nums; }
@media (forced-colors: active) {
  :root:has(> head > meta[name="color-scheme"][content]) {
    --primary: CanvasText;
    --secondary: CanvasText;
    --neutral: Canvas;
    --surface: Canvas;
    --hover: Canvas;
    --error: CanvasText;
    --error-surface: Canvas;
  }
}
